 * similarity scores than OpenAI models. Configurable via env var.
 */
const COSINE_THRESHOLD = parseFloat(
  process.env.TOTALRECLAW_COSINE_THRESHOLD ?? '0.15',
);

// ---------------------------------------------------------------------------
