/**
 * TotalReclaw Skill - Configuration Module
 *
 * Handles loading, merging, and validating configuration from multiple sources:
 * - skill.json defaults
 * - OpenClaw config (agents.defaults.totalreclaw.*)
 * - Environment variables (TOTALRECLAW_*)
 */

import type { TotalReclawSkillConfig } from './types';
import { DEFAULT_SKILL_CONFIG } from './types';

// ============================================================================
// Types
// ============================================================================

/**
 * Result of configuration validation
 */
export interface ConfigValidationResult {
  valid: boolean;
  errors: ConfigValidationError[];
  warnings: ConfigValidationWarning[];
}

/**
 * Configuration validation error
 */
export interface ConfigValidationError {
  field: string;
  value: unknown;
  message: string;
}

/**
 * Configuration validation warning
 */
export interface ConfigValidationWarning {
  field: string;
  value: unknown;
  message: string;
}

/**
 * OpenClaw configuration structure (subset we care about)
 */
interface OpenClawConfig {
  agents?: {
    defaults?: {
      totalreclaw?: Partial<TotalReclawSkillConfig>;
    };
  };
}

/**
 * Skill.json configuration defaults (extracted from skill.json)
 */
const SKILL_JSON_DEFAULTS: TotalReclawSkillConfig = {
  serverUrl: 'http://127.0.0.1:8080',
  autoExtractEveryTurns: 3,
  minImportanceForAutoStore: 6,
  maxMemoriesInContext: 8,
  forgetThreshold: 0.3,
  rerankerModel: 'BAAI/bge-reranker-base',
};

// ============================================================================
// Environment Variable Mapping
// ============================================================================

/**
 * Maps environment variable names to config keys and their parsers
 */
const ENV_VAR_MAPPING: Record<
  string,
  { key: keyof TotalReclawSkillConfig; parser: (value: string) => unknown }
> = {
  TOTALRECLAW_SERVER_URL: {
    key: 'serverUrl',
    parser: (v) => v,
  },
  TOTALRECLAW_AUTO_EXTRACT_EVERY_TURNS: {
    key: 'autoExtractEveryTurns',
    parser: (v) => parseInt(v, 10),
  },
  TOTALRECLAW_MIN_IMPORTANCE: {
    key: 'minImportanceForAutoStore',
    parser: (v) => parseInt(v, 10),
  },
  TOTALRECLAW_MAX_MEMORIES: {
    key: 'maxMemoriesInContext',
    parser: (v) => parseInt(v, 10),
  },
  TOTALRECLAW_FORGET_THRESHOLD: {
    key: 'forgetThreshold',
    parser: (v) => parseFloat(v),
  },
  TOTALRECLAW_RERANKER_MODEL: {
    key: 'rerankerModel',
    parser: (v) => v,
  },
  TOTALRECLAW_RECOVERY_PHRASE: {
    key: 'masterPassword',
    parser: (v) => v,
  },
  TOTALRECLAW_USER_ID: {
    key: 'userId',
    parser: (v) => v,
  },
};

// ============================================================================
// Configuration Loading
// ============================================================================

/**
 * Load configuration from environment variables
 *
 * @returns Partial config from environment variables
 */
function loadFromEnv(): Partial<TotalReclawSkillConfig> {
  const config: Partial<TotalReclawSkillConfig> = {};

  for (const [envVar, mapping] of Object.entries(ENV_VAR_MAPPING)) {
    const value = process.env[envVar];
    if (value !== undefined && value !== '') {
      try {
        (config as Record<string, unknown>)[mapping.key] = mapping.parser(value);
      } catch {
        // Skip invalid values - validation will catch them
        console.warn(`Failed to parse environment variable ${envVar}: ${value}`);
      }
    }
  }

  return config;
}

/**
 * Load configuration from OpenClaw config object
 *
 * @param openclawConfig - OpenClaw configuration object
 * @returns Partial config from OpenClaw
 */
function loadFromOpenClaw(openclawConfig?: OpenClawConfig): Partial<TotalReclawSkillConfig> {
  return openclawConfig?.agents?.defaults?.totalreclaw ?? {};
}

/**
 * Load skill.json defaults
 *
 * @returns Default configuration from skill.json
 */
function loadFromSkillJson(): TotalReclawSkillConfig {
  return { ...SKILL_JSON_DEFAULTS };
}

/**
 * Deep merge configuration objects
 * Later objects override earlier ones
 *
 * @param sources - Configuration sources to merge (in priority order, lowest first)
 * @returns Merged configuration
 */
function mergeConfigs(...sources: Partial<TotalReclawSkillConfig>[]): TotalReclawSkillConfig {
  const result = { ...DEFAULT_SKILL_CONFIG };

  for (const source of sources) {
    for (const [key, value] of Object.entries(source)) {
      if (value !== undefined) {
        (result as Record<string, unknown>)[key] = value;
      }
    }
  }

  return result;
}

/**
 * Load configuration from all sources with proper priority
 *
 * Priority order (highest last):
 * 1. skill.json defaults
 * 2. OpenClaw config (agents.defaults.totalreclaw.*)
 * 3. Environment variables (TOTALRECLAW_*)
 * 4. Explicit overrides (passed to this function)
 *
 * @param options - Loading options
 * @returns Complete, merged configuration
 */
export function loadConfig(options?: {
  /** OpenClaw configuration object */
  openclawConfig?: OpenClawConfig;
  /** Explicit configuration overrides */
  overrides?: Partial<TotalReclawSkillConfig>;
}): TotalReclawSkillConfig {
  const { openclawConfig, overrides } = options ?? {};

  // Load from all sources (in priority order, lowest to highest)
  const skillJsonDefaults = loadFromSkillJson();
  const openclawPartial = loadFromOpenClaw(openclawConfig);
  const envPartial = loadFromEnv();

  // Merge all sources (later sources override earlier ones)
  return mergeConfigs(skillJsonDefaults, openclawPartial, envPartial, overrides ?? {});
}

// ============================================================================
// Configuration Validation
// ============================================================================

/**
 * Validate that a string is a valid URL
 *
 * @param value - String to validate
 * @returns true if valid URL
 */
function isValidUrl(value: string): boolean {
  try {
    const url = new URL(value);
    return url.protocol === 'http:' || url.protocol === 'https:';
  } catch {
    return false;
  }
}

/**
 * Validate that a number is within a range (inclusive)
 *
 * @param value - Number to validate
 * @param min - Minimum value (inclusive)
 * @param max - Maximum value (inclusive)
 * @returns true if within range
 */
function isInRange(value: number, min: number, max: number): boolean {
  return typeof value === 'number' && !isNaN(value) && value >= min && value <= max;
}

/**
 * Field validators for configuration
 */
const FIELD_VALIDATORS: Record<
  keyof TotalReclawSkillConfig,
  {
    validate: (value: unknown) => boolean;
    getError: (value: unknown) => string;
    getWarning?: (value: unknown) => string | null;
    required?: boolean;
  }
> = {
  serverUrl: {
    validate: (v) => typeof v === 'string' && isValidUrl(v),
    getError: (v) => `Invalid serverUrl: "${v}" is not a valid HTTP/HTTPS URL`,
    getWarning: (v) => {
      if (typeof v === 'string' && v.startsWith('http://')) {
        return 'Using HTTP (not HTTPS) for serverUrl - not recommended for production';
      }
      return null;
    },
    required: true,
  },
  autoExtractEveryTurns: {
    validate: (v) => typeof v === 'number' && isInRange(v, 1, 100),
    getError: (v) => `Invalid autoExtractEveryTurns: ${v} (must be 1-100)`,
    required: true,
  },
  minImportanceForAutoStore: {
    validate: (v) => typeof v === 'number' && isInRange(v, 1, 10),
    getError: (v) => `Invalid minImportanceForAutoStore: ${v} (must be 1-10)`,
    required: true,
  },
  maxMemoriesInContext: {
    validate: (v) => typeof v === 'number' && isInRange(v, 1, 50),
    getError: (v) => `Invalid maxMemoriesInContext: ${v} (must be 1-50)`,
    getWarning: (v) => {
      if (typeof v === 'number' && v > 20) {
        return `High maxMemoriesInContext (${v}) may impact context window usage`;
      }
      return null;
    },
    required: true,
  },
  forgetThreshold: {
    validate: (v) => typeof v === 'number' && isInRange(v, 0, 1),
    getError: (v) => `Invalid forgetThreshold: ${v} (must be 0-1)`,
    getWarning: (v) => {
      if (typeof v === 'number') {
        if (v < 0.1) {
          return `Very low forgetThreshold (${v}) may cause memory bloat`;
        }
        if (v > 0.8) {
          return `High forgetThreshold (${v}) may cause excessive memory loss`;
        }
      }
      return null;
    },
    required: true,
  },
  rerankerModel: {
    validate: (v) => v === undefined || (typeof v === 'string' && v.length > 0),
    getError: (v) => `Invalid rerankerModel: ${v} (must be a non-empty string or undefined)`,
    required: false,
  },
  masterPassword: {
    validate: (v) => v === undefined || typeof v === 'string',
    getError: (v) => `Invalid masterPassword: must be a string or undefined`,
    required: false,
  },
  userId: {
    validate: (v) => v === undefined || typeof v === 'string',
    getError: (v) => `Invalid userId: must be a string or undefined`,
    required: false,
  },
  salt: {
    validate: (v) => v === undefined || Buffer.isBuffer(v),
    getError: (v) => `Invalid salt: must be a Buffer or undefined`,
    required: false,
  },
};

/**
 * Validate configuration values
 *
 * @param config - Configuration to validate
 * @returns Validation result with errors and warnings
 */
export function validateConfig(config: TotalReclawSkillConfig): ConfigValidationResult {
  const errors: ConfigValidationError[] = [];
  const warnings: ConfigValidationWarning[] = [];

  // Validate each field
  for (const [field, validator] of Object.entries(FIELD_VALIDATORS)) {
    const value = config[field as keyof TotalReclawSkillConfig];

    // Check required fields
    if (validator.required && value === undefined) {
      errors.push({
        field,
        value,
        message: `Missing required field: ${field}`,
      });
      continue;
    }

    // Skip validation for undefined optional fields
    if (value === undefined && !validator.required) {
      continue;
    }

    // Validate value
    if (!validator.validate(value)) {
      errors.push({
        field,
        value,
        message: validator.getError(value),
      });
    }

    // Check for warnings
    if (validator.getWarning) {
      const warning = validator.getWarning(value);
      if (warning) {
        warnings.push({
          field,
          value,
          message: warning,
        });
      }
    }
  }

  // Additional cross-field validations
  if (
    config.masterPassword &&
    typeof config.masterPassword === 'string' &&
    config.masterPassword.length < 12
  ) {
    warnings.push({
      field: 'masterPassword',
      value: '[REDACTED]',
      message: 'masterPassword is shorter than recommended (12+ characters)',
    });
  }

  return {
    valid: errors.length === 0,
    errors,
    warnings,
  };
}

// ============================================================================
// Utility Functions
// ============================================================================

/**
 * Assert that configuration is valid, throwing on errors
 *
 * @param config - Configuration to validate
 * @throws Error if configuration is invalid
 */
export function assertValidConfig(config: TotalReclawSkillConfig): void {
  const result = validateConfig(config);

  if (!result.valid) {
    const errorMessages = result.errors.map((e) => `  - ${e.field}: ${e.message}`).join('\n');
    throw new Error(`Invalid TotalReclaw configuration:\n${errorMessages}`);
  }

  // Log warnings
  for (const warning of result.warnings) {
    console.warn(`[TotalReclaw] Config warning - ${warning.field}: ${warning.message}`);
  }
}

/**
 * Create a configuration with defaults and validate it
 *
 * @param partial - Partial configuration to merge with defaults
 * @param options - Additional loading options
 * @returns Validated, complete configuration
 * @throws Error if resulting configuration is invalid
 */
export function createConfig(
  partial?: Partial<TotalReclawSkillConfig>,
  options?: Parameters<typeof loadConfig>[0],
): TotalReclawSkillConfig {
  const config = loadConfig({
    ...options,
    overrides: partial,
  });

  assertValidConfig(config);
  return config;
}

/**
 * Debug logging utility for TotalReclaw Skill
 *
 * Logging is gated behind TOTALRECLAW_DEBUG=true (env var) OR an explicit
 * `enabled` override passed by callers that have their own debug flag.
 * Production builds are silent by default.
 */

const DEBUG = process.env.TOTALRECLAW_DEBUG === 'true';

/**
 * Log a debug message.
 *
 * Silent unless TOTALRECLAW_DEBUG=true OR the caller passes `enabled: true`.
 * The optional first boolean argument acts as a local override so that
 * hook-level `options.debug` flags still work.
 */
export function debugLog(enabled: boolean, ...args: unknown[]): void;
export function debugLog(...args: unknown[]): void;
export function debugLog(...args: unknown[]): void {
  let enabled: boolean;
  let rest: unknown[];

  if (typeof args[0] === 'boolean') {
    enabled = args[0] || DEBUG;
    rest = args.slice(1);
  } else {
    enabled = DEBUG;
    rest = args;
  }

  if (enabled) {
    console.log('[TotalReclaw]', ...rest);
  }
}

/**
 * TotalReclaw Skill - Deduplication Logic
 *
 * Handles detection of duplicate facts using:
 * 1. Vector similarity for initial candidate retrieval
 * 2. LLM judge for final ADD/UPDATE/DELETE decision
 * 3. Contradiction handling for conflicting facts
 */

import type { ExtractedFact, Entity, Relation, ExtractionAction } from '../types';
import {
  DEDUP_JUDGE_PROMPT,
  CONTRADICTION_DETECTION_PROMPT,
  formatExistingMemories,
  validateExtractionResponse
} from './prompts';

// ============================================================================
// Types
// ============================================================================

/**
 * Result from deduplication check
 */
export interface DedupResult {
  /** The determined action */
  action: ExtractionAction;
  /** ID of existing fact if UPDATE or DELETE */
  existingFactId?: string;
  /** Confidence in the decision */
  confidence: number;
  /** Reasoning for the decision */
  reasoning: string;
}

/**
 * Existing fact from memory store
 */
export interface ExistingFact {
  id: string;
  factText: string;
  type: ExtractedFact['type'];
  importance: number;
  embedding?: number[];
  entities?: Entity[];
  relations?: Relation[];
}

/**
 * LLM client interface (to be implemented by consumer)
 */
export interface LLMClient {
  complete(prompt: { system: string; user: string }): Promise<string>;
}

/**
 * Vector store client interface (to be implemented by consumer)
 */
export interface VectorStoreClient {
  /**
   * Find similar facts by embedding
   */
  findSimilar(embedding: number[], k: number): Promise<ExistingFact[]>;

  /**
   * Get embedding for text
   */
  getEmbedding(text: string): Promise<number[]>;
}

/**
 * Configuration for deduplication
 */
export interface DedupConfig {
  /** Similarity threshold for considering facts as duplicates (0-1) */
  similarityThreshold: number;
  /** Number of similar facts to retrieve for comparison */
  topK: number;
  /** Whether to use LLM judge for final decision */
  useLLMJudge: boolean;
  /** Minimum confidence to override default ADD decision */
  minConfidenceForOverride: number;
}

/**
 * Default deduplication configuration
 */
export const DEFAULT_DEDUP_CONFIG: DedupConfig = {
  similarityThreshold: 0.85,
  topK: 5,
  useLLMJudge: true,
  minConfidenceForOverride: 0.7
};

// ============================================================================
// Deduplication Class
// ============================================================================

/**
 * Fact deduplicator that uses vector similarity + LLM judge
 */
export class FactDeduplicator {
  private config: DedupConfig;
  private llmClient: LLMClient | null;
  private vectorStore: VectorStoreClient | null;

  constructor(
    config: Partial<DedupConfig> = {},
    llmClient?: LLMClient,
    vectorStore?: VectorStoreClient
  ) {
    this.config = { ...DEFAULT_DEDUP_CONFIG, ...config };
    this.llmClient = llmClient || null;
    this.vectorStore = vectorStore || null;
  }

  /**
   * Check if a fact should be ADD/UPDATE/DELETE/NOOP
   */
  async checkDuplication(fact: ExtractedFact): Promise<DedupResult> {
    // If no vector store, use simple text-based comparison
    if (!this.vectorStore) {
      return this.textBasedDedup(fact);
    }

    // Get embedding for the fact
    const embedding = await this.vectorStore.getEmbedding(fact.factText);

    // Find similar existing facts
    const similarFacts = await this.vectorStore.findSimilar(embedding, this.config.topK);

    // Filter by similarity threshold
    const candidates = similarFacts.filter(f =>
      this.calculateCosineSimilarity(embedding, f.embedding || []) >= this.config.similarityThreshold
    );

    // No similar facts found - ADD
    if (candidates.length === 0) {
      return {
        action: 'ADD',
        confidence: 0.95,
        reasoning: 'No similar existing facts found'
      };
    }

    // Use LLM judge if available and enabled
    if (this.config.useLLMJudge && this.llmClient) {
      return this.llmJudgeDedup(fact, candidates);
    }

    // Fall back to heuristic-based decision
    return this.heuristicDedup(fact, candidates);
  }

  /**
   * Deduplicate multiple facts against existing memories
   */
  async deduplicateFacts(
    facts: ExtractedFact[],
    existingFacts: ExistingFact[]
  ): Promise<ExtractedFact[]> {
    const results: ExtractedFact[] = [];

    for (const fact of facts) {
      // Find similar existing facts
      const candidates = await this.findSimilarFacts(fact, existingFacts);

      if (candidates.length === 0) {
        // No similar facts - keep as ADD
        results.push({ ...fact, action: fact.action || 'ADD' });
        continue;
      }

      // Determine action using LLM judge or heuristics
      const dedupResult = await this.checkDuplication(fact);

      // Apply the dedup result
      results.push({
        ...fact,
        action: dedupResult.action,
        existingFactId: dedupResult.existingFactId,
        confidence: Math.min(fact.confidence, dedupResult.confidence)
      });
    }

    return results;
  }

  /**
   * Find similar facts from a list of existing facts
   */
  private async findSimilarFacts(
    fact: ExtractedFact,
    existingFacts: ExistingFact[]
  ): Promise<ExistingFact[]> {
    if (!this.vectorStore) {
      // Text-based similarity
      return existingFacts.filter(ef =>
        this.textSimilarity(fact.factText, ef.factText) >= this.config.similarityThreshold
      );
    }

    const embedding = await this.vectorStore.getEmbedding(fact.factText);

    return existingFacts.filter(ef => {
      if (!ef.embedding) return false;
      return this.calculateCosineSimilarity(embedding, ef.embedding) >= this.config.similarityThreshold;
    });
  }

  /**
   * Use LLM to judge ADD vs UPDATE vs DELETE
   */
  private async llmJudgeDedup(fact: ExtractedFact, candidates: ExistingFact[]): Promise<DedupResult> {
    if (!this.llmClient) {
      return this.heuristicDedup(fact, candidates);
    }

    const prompt = DEDUP_JUDGE_PROMPT.format({
      newFact: this.formatFactForJudge(fact),
      existingFacts: candidates.map((c, i) =>
        `[${i + 1}] ID: ${c.id}\n    Type: ${c.type}\n    Importance: ${c.importance}\n    Fact: ${c.factText}`
      ).join('\n\n')
    });

    try {
      const response = await this.llmClient.complete(prompt);
      const parsed = JSON.parse(response);

      return {
        action: this.validateAction(parsed.decision),
        existingFactId: parsed.existingFactId,
        confidence: Math.max(0, Math.min(1, parsed.confidence || 0.8)),
        reasoning: parsed.reasoning || 'LLM judge decision'
      };
    } catch (error) {
      console.error('LLM judge failed, falling back to heuristics:', error);
      return this.heuristicDedup(fact, candidates);
    }
  }

  /**
   * Heuristic-based deduplication (no LLM)
   */
  private heuristicDedup(fact: ExtractedFact, candidates: ExistingFact[]): DedupResult {
    // Check for near-exact match
    for (const candidate of candidates) {
      const similarity = this.textSimilarity(fact.factText, candidate.factText);

      // Very high similarity - likely duplicate
      if (similarity >= 0.95) {
        return {
          action: 'NOOP',
          existingFactId: candidate.id,
          confidence: 0.9,
          reasoning: `Near-exact match with existing fact (similarity: ${similarity.toFixed(2)})`
        };
      }

      // Check for contradiction
      if (this.isLikelyContradiction(fact.factText, candidate.factText)) {
        return {
          action: 'DELETE',
          existingFactId: candidate.id,
          confidence: 0.7,
          reasoning: 'Likely contradiction with existing fact'
        };
      }
    }

    // Check for refinement/update
    const bestMatch = candidates[0];
    if (bestMatch && this.textSimilarity(fact.factText, bestMatch.factText) >= 0.7) {
      return {
        action: 'UPDATE',
        existingFactId: bestMatch.id,
        confidence: 0.7,
        reasoning: 'Likely update/refinement of existing fact'
      };
    }

    // Default to ADD
    return {
      action: 'ADD',
      confidence: 0.8,
      reasoning: 'No sufficient similarity to existing facts'
    };
  }

  /**
   * Text-based deduplication when no vector store is available
   */
  private textBasedDedup(fact: ExtractedFact): DedupResult {
    // Without vector store or LLM, we rely on the fact's own action
    // and do simple text comparison
    return {
      action: fact.action || 'ADD',
      confidence: 0.6,
      reasoning: 'Text-based deduplication (no vector store available)'
    };
  }

  /**
   * Detect if two facts are likely contradictions
   */
  async detectContradiction(
    factA: string,
    factB: string
  ): Promise<{ isContradiction: boolean; type: string; reasoning: string }> {
    // Heuristic contradiction detection
    const heuristicsResult = this.isLikelyContradictionDetailed(factA, factB);

    // If LLM is available, use it for more accurate detection
    if (this.llmClient && heuristicsResult.confidence < 0.8) {
      return this.llmContradictionDetection(factA, factB);
    }

    return heuristicsResult;
  }

  /**
   * Use LLM for contradiction detection
   */
  private async llmContradictionDetection(
    factA: string,
    factB: string
  ): Promise<{ isContradiction: boolean; type: string; reasoning: string }> {
    if (!this.llmClient) {
      return { isContradiction: false, type: 'none', reasoning: 'No LLM available' };
    }

    const prompt = CONTRADICTION_DETECTION_PROMPT.format({
      factA,
      factB
    });

    try {
      const response = await this.llmClient.complete(prompt);
      const parsed = JSON.parse(response);

      return {
        isContradiction: parsed.isContradiction || false,
        type: parsed.contradictionType || 'none',
        reasoning: parsed.reasoning || 'LLM detection'
      };
    } catch (error) {
      console.error('LLM contradiction detection failed:', error);
      return { isContradiction: false, type: 'none', reasoning: 'LLM error' };
    }
  }

  // ============================================================================
  // Utility Methods
  // ============================================================================

  /**
   * Calculate cosine similarity between two vectors
   */
  private calculateCosineSimilarity(a: number[], b: number[]): number {
    if (a.length !== b.length || a.length === 0) return 0;

    let dotProduct = 0;
    let normA = 0;
    let normB = 0;

    for (let i = 0; i < a.length; i++) {
      dotProduct += a[i] * b[i];
      normA += a[i] * a[i];
      normB += b[i] * b[i];
    }

    if (normA === 0 || normB === 0) return 0;

    return dotProduct / (Math.sqrt(normA) * Math.sqrt(normB));
  }

  /**
   * Calculate text similarity using Jaccard similarity on words
   */
  private textSimilarity(a: string, b: string): number {
    const wordsA = new Set(a.toLowerCase().split(/\s+/).filter(w => w.length > 2));
    const wordsB = new Set(b.toLowerCase().split(/\s+/).filter(w => w.length > 2));

    if (wordsA.size === 0 || wordsB.size === 0) return 0;

    const intersection = new Set(Array.from(wordsA).filter(x => wordsB.has(x)));
    const union = new Set([...Array.from(wordsA), ...Array.from(wordsB)]);

    return intersection.size / union.size;
  }

  /**
   * Quick check if two facts are likely contradictions
   */
  private isLikelyContradiction(a: string, b: string): boolean {
    const contradictionPatterns = [
      /\b(?:not|never|don't|doesn't|won't|can't)\b.*\b(?:like|prefer|use|want|need)\b/i,
      /\b(?:hate|dislike|avoid)\b.*\b(?:vs|instead of|rather than)\b/i
    ];

    // Check if one fact negates keywords in the other
    const aLower = a.toLowerCase();
    const bLower = b.toLowerCase();

    for (const pattern of contradictionPatterns) {
      if ((pattern.test(a) && !pattern.test(b)) || (pattern.test(b) && !pattern.test(a))) {
        // Check if they share significant content
        const similarity = this.textSimilarity(a, b);
        if (similarity >= 0.3) {
          return true;
        }
      }
    }

    return false;
  }

  /**
   * Detailed contradiction detection
   */
  private isLikelyContradictionDetailed(
    a: string,
    b: string
  ): { isContradiction: boolean; type: string; reasoning: string; confidence: number } {
    const aLower = a.toLowerCase();
    const bLower = b.toLowerCase();

    // Direct negation patterns
    const negationWords = ['not', 'never', "don't", "doesn't", "won't", "can't", 'no'];
    const hasNegationA = negationWords.some(w => aLower.includes(` ${w} `) || aLower.startsWith(`${w} `));
    const hasNegationB = negationWords.some(w => bLower.includes(` ${w} `) || bLower.startsWith(`${w} `));

    if (hasNegationA !== hasNegationB) {
      const similarity = this.textSimilarity(a, b);
      if (similarity >= 0.4) {
        return {
          isContradiction: true,
          type: 'direct_negation',
          reasoning: 'One fact contains negation while the other does not, with significant content overlap',
          confidence: 0.7
        };
      }
    }

    // Mutually exclusive value patterns
    const valuePatterns = [
      { pattern: /\b(?:uses?|prefers?|likes?)\s+(\w+)/i, type: 'mutually_exclusive' }
    ];

    // Check for temporal replacement keywords
    const temporalKeywords = ['now', 'currently', 'formerly', 'used to', 'previously', 'moved to', 'switched to'];
    const hasTemporalA = temporalKeywords.some(k => aLower.includes(k));
    const hasTemporalB = temporalKeywords.some(k => bLower.includes(k));

    if (hasTemporalA || hasTemporalB) {
      const similarity = this.textSimilarity(a, b);
      if (similarity >= 0.3) {
        return {
          isContradiction: true,
          type: 'temporal_replacement',
          reasoning: 'Temporal keywords suggest state change',
          confidence: 0.6
        };
      }
    }

    return {
      isContradiction: false,
      type: 'none',
      reasoning: 'No contradiction patterns detected',
      confidence: 0.5
    };
  }

  /**
   * Format a fact for the LLM judge
   */
  private formatFactForJudge(fact: ExtractedFact): string {
    const parts = [
      `Text: ${fact.factText}`,
      `Type: ${fact.type}`,
      `Importance: ${fact.importance}`,
      `Confidence: ${fact.confidence}`
    ];

    if (fact.entities.length > 0) {
      parts.push(`Entities: ${fact.entities.map(e => `${e.name} (${e.type})`).join(', ')}`);
    }

    if (fact.relations.length > 0) {
      parts.push(`Relations: ${fact.relations.map(r => `${r.subjectId} -> ${r.predicate} -> ${r.objectId}`).join(', ')}`);
    }

    return parts.join('\n');
  }

  /**
   * Validate and normalize action
   */
  private validateAction(action: unknown): ExtractionAction {
    const validActions: ExtractionAction[] = ['ADD', 'UPDATE', 'DELETE', 'NOOP'];
    if (validActions.includes(action as ExtractionAction)) {
      return action as ExtractionAction;
    }
    return 'ADD';
  }
}

// ============================================================================
// Helper Functions
// ============================================================================

/**
 * Create a deduplicator with default configuration
 */
export function createDeduplicator(
  llmClient?: LLMClient,
  vectorStore?: VectorStoreClient,
  config?: Partial<DedupConfig>
): FactDeduplicator {
  return new FactDeduplicator(config, llmClient, vectorStore);
}

/**
 * Quick check if two fact texts are semantically similar
 */
export async function areFactsSimilar(
  factA: string,
  factB: string,
  vectorStore?: VectorStoreClient
): Promise<boolean> {
  if (!vectorStore) {
    // Fall back to text similarity
    const wordsA = new Set(factA.toLowerCase().split(/\s+/).filter(w => w.length > 2));
    const wordsB = new Set(factB.toLowerCase().split(/\s+/).filter(w => w.length > 2));

    if (wordsA.size === 0 || wordsB.size === 0) return false;

    const intersection = new Set(Array.from(wordsA).filter(x => wordsB.has(x)));
    const union = new Set([...Array.from(wordsA), ...Array.from(wordsB)]);

    return (intersection.size / union.size) >= 0.7;
  }

  const [embA, embB] = await Promise.all([
    vectorStore.getEmbedding(factA),
    vectorStore.getEmbedding(factB)
  ]);

  // Calculate cosine similarity
  let dotProduct = 0;
  let normA = 0;
  let normB = 0;

  for (let i = 0; i < embA.length; i++) {
    dotProduct += embA[i] * embB[i];
    normA += embA[i] * embA[i];
    normB += embB[i] * embB[i];
  }

  if (normA === 0 || normB === 0) return false;

  const similarity = dotProduct / (Math.sqrt(normA) * Math.sqrt(normB));
  return similarity >= 0.85;
}

/**
 * Merge two facts (for UPDATE operations)
 */
export function mergeFacts(
  existing: ExistingFact,
  update: ExtractedFact
): ExtractedFact {
  // Merge entities (prefer new entities but keep stable IDs)
  const mergedEntities = [...existing.entities || []];
  for (const entity of update.entities) {
    const existingIdx = mergedEntities.findIndex(
      e => e.name.toLowerCase() === entity.name.toLowerCase() && e.type === entity.type
    );
    if (existingIdx === -1) {
      mergedEntities.push(entity);
    }
  }

  // Merge relations (prefer new relations)
  const mergedRelations = [...existing.relations || []];
  for (const relation of update.relations) {
    const exists = mergedRelations.some(
      r => r.subjectId === relation.subjectId &&
           r.predicate === relation.predicate &&
           r.objectId === relation.objectId
    );
    if (!exists) {
      mergedRelations.push(relation);
    }
  }

  return {
    ...update,
    existingFactId: existing.id,
    entities: mergedEntities,
    relations: mergedRelations,
    // Take higher importance
    importance: Math.max(existing.importance, update.importance)
  };
}

/**
 * TotalReclaw Skill - Fact Extractor
 *
 * Main extraction module that:
 * 1. Extracts facts from conversation context
 * 2. Deduplicates against existing memories
 * 3. Scores importance
 * 4. Extracts entities and relations
 */

import type {
  ExtractedFact,
  ExtractionResult,
  OpenClawContext,
  Entity,
  Relation,
  ExtractionAction
} from '../types';
import {
  PRE_COMPACTION_PROMPT,
  POST_TURN_PROMPT,
  EXPLICIT_COMMAND_PROMPT,
  ENTITY_EXTRACTION_PROMPT,
  formatConversationHistory,
  formatExistingMemories,
  generateEntityId,
  validateExtractionResponse,
  EXTRACTION_RESPONSE_SCHEMA
} from './prompts';
import {
  FactDeduplicator,
  createDeduplicator,
  type ExistingFact,
  type LLMClient,
  type VectorStoreClient,
  type DedupConfig
} from './dedup';

// ============================================================================
// Types
// ============================================================================

/**
 * Extraction trigger type
 */
export type ExtractionTrigger = 'pre_compaction' | 'post_turn' | 'explicit';

/**
 * Configuration for the fact extractor
 */
export interface FactExtractorConfig {
  /** Model to use for extraction (e.g., "claude-3-5-haiku") */
  extractionModel?: string;
  /** Temperature for extraction */
  extractionTemperature?: number;
  /** Minimum importance to include in results */
  minImportance?: number;
  /** Whether to auto-deduplicate */
  autoDeduplicate?: boolean;
  /** Number of turns to include in post-turn extraction */
  postTurnWindow?: number;
  /** Number of turns to include in pre-compaction extraction */
  preCompactionWindow?: number;
  /** Deduplication configuration */
  dedupConfig?: Partial<DedupConfig>;
}

/**
 * Default extraction configuration
 */
export const DEFAULT_EXTRACTOR_CONFIG: Required<Omit<FactExtractorConfig, 'dedupConfig'>> & {
  dedupConfig: Partial<DedupConfig>;
} = {
  extractionModel: 'claude-3-5-haiku-20241022',
  extractionTemperature: 0.3,
  minImportance: 1,
  autoDeduplicate: true,
  postTurnWindow: 3,
  preCompactionWindow: 20,
  dedupConfig: {}
};

/**
 * LLM response structure
 */
interface LLMExtractionResponse {
  facts: Array<{
    factText: string;
    type: ExtractedFact['type'];
    importance: number;
    confidence: number;
    action: ExtractionAction;
    existingFactId?: string;
    entities: Array<{
      id: string;
      name: string;
      type: string;
    }>;
    relations: Array<{
      subjectId: string;
      predicate: string;
      objectId: string;
      confidence: number;
    }>;
    reasoning?: string;
  }>;
  metadata?: {
    totalTurnsAnalyzed: number;
    extractionTimestamp: string;
  };
}

// ============================================================================
// Fact Extractor Class
// ============================================================================

/**
 * Main fact extraction class
 */
export class FactExtractor {
  private config: Required<Omit<FactExtractorConfig, 'dedupConfig'>> & { dedupConfig: Partial<DedupConfig> };
  private llmClient: LLMClient;
  private vectorStore: VectorStoreClient | null;
  private deduplicator: FactDeduplicator;

  constructor(
    llmClient: LLMClient,
    vectorStore?: VectorStoreClient,
    config: Partial<FactExtractorConfig> = {}
  ) {
    this.config = {
      ...DEFAULT_EXTRACTOR_CONFIG,
      ...config
    };
    this.llmClient = llmClient;
    this.vectorStore = vectorStore || null;
    this.deduplicator = createDeduplicator(llmClient, vectorStore, this.config.dedupConfig);
  }

  /**
   * Extract facts from OpenClaw context
   */
  async extractFacts(
    context: OpenClawContext,
    trigger: ExtractionTrigger = 'post_turn'
  ): Promise<ExtractionResult> {
    const startTime = Date.now();

    // Select appropriate prompt based on trigger
    const prompt = this.selectPrompt(context, trigger);

    // Call LLM for extraction
    const rawResponse = await this.llmClient.complete(prompt);

    // Parse and validate response
    const { facts, errors } = await this.parseExtractionResponse(rawResponse);

    if (errors.length > 0) {
      console.warn('Extraction validation warnings:', errors);
    }

    // Filter by minimum importance
    const filteredFacts = facts.filter(f => f.importance >= this.config.minImportance);

    // Post-process: normalize entities and relations
    const processedFacts = filteredFacts.map(fact => this.postProcessFact(fact));

    return {
      facts: processedFacts,
      rawResponse,
      processingTimeMs: Date.now() - startTime
    };
  }

  /**
   * Deduplicate extracted facts against existing memories
   */
  async deduplicateAgainstExisting(
    facts: ExtractedFact[],
    existingFacts: ExistingFact[]
  ): Promise<ExtractedFact[]> {
    if (!this.config.autoDeduplicate) {
      return facts;
    }

    return this.deduplicator.deduplicateFacts(facts, existingFacts);
  }

  /**
   * Score importance of a fact (1-10 scale)
   * Can be used to re-score or validate LLM scores
   */
  scoreImportance(fact: ExtractedFact): number {
    let score = fact.importance;

    // Boost for explicit user requests
    if (fact.action === 'ADD' && fact.confidence > 0.9) {
      score = Math.min(10, score + 1);
    }

    // Boost for decisions (they tend to be important)
    if (fact.type === 'decision') {
      score = Math.min(10, score + 1);
    }

    // Boost for goals
    if (fact.type === 'goal') {
      score = Math.min(10, score + 0.5);
    }

    // Reduce for low confidence
    if (fact.confidence < 0.5) {
      score = Math.max(1, score - 1);
    }

    return Math.round(score);
  }

  /**
   * Extract entities from text (standalone entity extraction)
   */
  async extractEntities(text: string): Promise<Entity[]> {
    const prompt = ENTITY_EXTRACTION_PROMPT.format(text);

    try {
      const response = await this.llmClient.complete(prompt);
      const parsed = JSON.parse(response);

      if (!Array.isArray(parsed.entities)) {
        return [];
      }

      return parsed.entities.map((e: { id?: string; name: string; type: string }) => ({
        id: e.id || generateEntityId(e.name, e.type),
        name: e.name,
        type: e.type
      }));
    } catch (error) {
      console.error('Entity extraction failed:', error);
      return [];
    }
  }

  /**
   * Extract relations from a fact
   */
  async extractRelations(fact: ExtractedFact): Promise<Relation[]> {
    // If relations already extracted by LLM, validate and return
    if (fact.relations.length > 0) {
      return fact.relations.filter(r =>
        r.subjectId &&
        r.predicate &&
        r.objectId &&
        r.confidence >= 0 &&
        r.confidence <= 1
      );
    }

    // Otherwise, extract relations from entities
    const relations: Relation[] = [];
    const entities = fact.entities;

    // Generate "mentions" relations between entities
    for (let i = 0; i < entities.length; i++) {
      for (let j = i + 1; j < entities.length; j++) {
        // Infer relation type based on fact type
        let predicate = 'related_to';

        if (fact.type === 'preference') {
          predicate = 'prefers_with';
        } else if (fact.type === 'decision') {
          predicate = 'decided_with';
        }

        relations.push({
          subjectId: entities[i].id,
          predicate,
          objectId: entities[j].id,
          confidence: 0.5 // Lower confidence for inferred relations
        });
      }
    }

    return relations;
  }

  // ============================================================================
  // Private Methods
  // ============================================================================

  /**
   * Select the appropriate prompt based on trigger type
   */
  private selectPrompt(
    context: OpenClawContext,
    trigger: ExtractionTrigger
  ): { system: string; user: string } {
    switch (trigger) {
      case 'pre_compaction':
        return this.buildPreCompactionPrompt(context);

      case 'explicit':
        return this.buildExplicitPrompt(context);

      case 'post_turn':
      default:
        return this.buildPostTurnPrompt(context);
    }
  }

  /**
   * Build pre-compaction extraction prompt
   */
  private buildPreCompactionPrompt(context: OpenClawContext): { system: string; user: string } {
    // Get last N turns
    const turns = context.history.slice(-this.config.preCompactionWindow);
    const historyStr = formatConversationHistory(turns);

    // Get existing memories for dedup context
    const existingMemoriesStr = '(Existing memories will be checked during deduplication)';

    return PRE_COMPACTION_PROMPT.format({
      conversationHistory: historyStr,
      existingMemories: existingMemoriesStr
    });
  }

  /**
   * Build post-turn extraction prompt
   */
  private buildPostTurnPrompt(context: OpenClawContext): { system: string; user: string } {
    // Get last N turns
    const turns = context.history.slice(-this.config.postTurnWindow);
    const historyStr = formatConversationHistory(turns);

    // Include current message if not in history
    const fullHistory = turns.length === 0 || turns[turns.length - 1]?.content !== context.userMessage
      ? `${historyStr}\n\n[LATEST] USER:\n${context.userMessage}`
      : historyStr;

    const existingMemoriesStr = '(Existing memories will be checked during deduplication)';

    return POST_TURN_PROMPT.format({
      conversationHistory: fullHistory,
      existingMemories: existingMemoriesStr
    });
  }

  /**
   * Build explicit command extraction prompt
   */
  private buildExplicitPrompt(context: OpenClawContext): { system: string; user: string } {
    // The user message should contain the explicit request
    const turns = context.history.slice(-5);
    const contextStr = formatConversationHistory(turns);

    return EXPLICIT_COMMAND_PROMPT.format({
      userRequest: context.userMessage,
      conversationContext: contextStr
    });
  }

  /**
   * Parse and validate LLM extraction response
   */
  private async parseExtractionResponse(
    rawResponse: string
  ): Promise<{ facts: ExtractedFact[]; errors: string[] }> {
    const errors: string[] = [];

    try {
      // Try to extract JSON from the response
      let jsonStr = rawResponse;

      // Handle markdown code blocks
      const jsonMatch = rawResponse.match(/```(?:json)?\s*([\s\S]*?)```/);
      if (jsonMatch) {
        jsonStr = jsonMatch[1].trim();
      }

      const parsed: LLMExtractionResponse = JSON.parse(jsonStr);

      if (!Array.isArray(parsed.facts)) {
        return { facts: [], errors: ['Response does not contain a facts array'] };
      }

      // Validate each fact
      const facts: ExtractedFact[] = [];

      for (let i = 0; i < parsed.facts.length; i++) {
        const rawFact = parsed.facts[i];
        const validation = this.validateFact(rawFact, i);

        if (validation.errors.length > 0) {
          errors.push(...validation.errors);
        }

        if (validation.fact) {
          facts.push(validation.fact);
        }
      }

      return { facts, errors };
    } catch (error) {
      const errorMsg = error instanceof Error ? error.message : 'Unknown parsing error';
      return { facts: [], errors: [`Failed to parse LLM response: ${errorMsg}`] };
    }
  }

  /**
   * Validate a single extracted fact
   */
  private validateFact(
    rawFact: LLMExtractionResponse['facts'][0],
    index: number
  ): { fact: ExtractedFact | null; errors: string[] } {
    const errors: string[] = [];
    const prefix = `facts[${index}]`;

    // Validate required fields
    if (!rawFact.factText || typeof rawFact.factText !== 'string') {
      errors.push(`${prefix}.factText must be a non-empty string`);
    }

    const validTypes: ExtractedFact['type'][] = ['fact', 'preference', 'decision', 'episodic', 'goal', 'context', 'summary'];
    if (!validTypes.includes(rawFact.type)) {
      errors.push(`${prefix}.type must be one of: ${validTypes.join(', ')}`);
    }

    if (typeof rawFact.importance !== 'number' || rawFact.importance < 1 || rawFact.importance > 10) {
      errors.push(`${prefix}.importance must be a number between 1 and 10`);
    }

    if (typeof rawFact.confidence !== 'number' || rawFact.confidence < 0 || rawFact.confidence > 1) {
      errors.push(`${prefix}.confidence must be a number between 0 and 1`);
    }

    const validActions: ExtractionAction[] = ['ADD', 'UPDATE', 'DELETE', 'NOOP'];
    if (!validActions.includes(rawFact.action)) {
      errors.push(`${prefix}.action must be one of: ${validActions.join(', ')}`);
    }

    if (errors.length > 0) {
      return { fact: null, errors };
    }

    // Build validated fact
    const fact: ExtractedFact = {
      factText: rawFact.factText.trim().slice(0, 512), // Limit length
      type: rawFact.type,
      importance: Math.round(Math.max(1, Math.min(10, rawFact.importance))),
      confidence: Math.max(0, Math.min(1, rawFact.confidence)),
      action: rawFact.action,
      existingFactId: rawFact.existingFactId,
      entities: (rawFact.entities || []).map(e => ({
        id: e.id || generateEntityId(e.name, e.type),
        name: e.name,
        type: e.type
      })),
      relations: (rawFact.relations || []).filter(r =>
        r.subjectId && r.predicate && r.objectId
      ).map(r => ({
        subjectId: r.subjectId,
        predicate: r.predicate,
        objectId: r.objectId,
        confidence: Math.max(0, Math.min(1, r.confidence || 0.5))
      }))
    };

    return { fact, errors: [] };
  }

  /**
   * Post-process a fact (normalize entities, etc.)
   */
  private postProcessFact(fact: ExtractedFact): ExtractedFact {
    // Normalize entity IDs
    const normalizedEntities = fact.entities.map(entity => ({
      ...entity,
      id: entity.id || generateEntityId(entity.name, entity.type)
    }));

    // Update relation subject/object IDs to match normalized entity IDs
    const entityMap = new Map(normalizedEntities.map(e => [e.name.toLowerCase(), e.id]));

    const normalizedRelations = fact.relations.map(relation => {
      // Try to find matching entity IDs
      let subjectId = relation.subjectId;
      let objectId = relation.objectId;

      // If relation uses entity names instead of IDs, try to resolve
      for (const entry of Array.from(entityMap.entries())) {
        const [name, id] = entry;
        if (relation.subjectId.toLowerCase().includes(name)) {
          subjectId = id;
        }
        if (relation.objectId.toLowerCase().includes(name)) {
          objectId = id;
        }
      }

      return {
        ...relation,
        subjectId,
        objectId
      };
    });

    // Re-score importance
    const importance = this.scoreImportance(fact);

    return {
      ...fact,
      entities: normalizedEntities,
      relations: normalizedRelations,
      importance
    };
  }
}

