    await skill.remember({ text: 'Memory 2' });
    await skill.remember({ text: 'Memory 3' });

    // Export all
    const exportResult = await skill.export({ format: 'json' });
    const parsed = JSON.parse(exportResult);

    expect(parsed.facts).toBeDefined();
  });
});
